CREATE TRIGGER commerce_item_refunded AFTER UPDATE OF refunded_quantity ON commerce_order_items WHEN NEW.refunded_quantity>OLD.refunded_quantity BEGIN
 UPDATE commerce_skus SET stock=stock+NEW.refunded_quantity-OLD.refunded_quantity WHERE id=NEW.sku_id AND (NEW.type!='physical' OR EXISTS(SELECT 1 FROM commerce_orders WHERE id=NEW.order_id AND fulfillment_status NOT IN ('shipped','delivered')));
 INSERT INTO commerce_inventory_events SELECT 'refund:'||NEW.id||':'||NEW.refunded_quantity,o.owner,'sandbox',NEW.order_id,NEW.id,NEW.sku_id,CASE WHEN NEW.type='physical' AND o.fulfillment_status IN ('shipped','delivered') THEN 0 ELSE NEW.refunded_quantity-OLD.refunded_quantity END,CASE WHEN NEW.type='physical' AND o.fulfillment_status IN ('shipped','delivered') THEN 'refund_after_dispatch_no_restock' ELSE 'refund_restock' END,(SELECT max(created) FROM commerce_payment_events WHERE order_id=NEW.order_id) FROM commerce_orders o WHERE o.id=NEW.order_id;
 UPDATE commerce_entitlements SET remaining=NEW.quantity-NEW.refunded_quantity,status=CASE WHEN NEW.quantity=NEW.refunded_quantity THEN 'revoked' ELSE 'active' END,updated=(SELECT max(created) FROM commerce_payment_events WHERE order_id=NEW.order_id) WHERE item_id=NEW.id AND environment='sandbox';
END

CREATE TRIGGER commerce_order_paid AFTER UPDATE OF payment_status ON commerce_orders WHEN OLD.payment_status='unpaid' AND NEW.payment_status='paid' BEGIN
 UPDATE commerce_reservations SET state='consumed' WHERE order_id=NEW.id AND state='held';
 INSERT INTO commerce_entitlements SELECT 'sandbox:'||i.id,NEW.owner,'sandbox',NEW.id,i.id,i.content_id,i.type,i.quantity,i.quantity,'active',NEW.updated,NEW.updated FROM commerce_order_items i WHERE i.order_id=NEW.id AND i.type IN ('digital','membership');
END

CREATE TRIGGER commerce_refund_apply AFTER INSERT ON commerce_payment_events WHEN NEW.kind='refund' BEGIN
 UPDATE commerce_order_items SET refunded_quantity=refunded_quantity+(SELECT json_extract(j.value,'$.quantity') FROM json_each(NEW.items) j WHERE json_extract(j.value,'$.itemId')=commerce_order_items.id) WHERE order_id=NEW.order_id AND id IN (SELECT json_extract(value,'$.itemId') FROM json_each(NEW.items));
 UPDATE commerce_orders SET refunded_minor=refunded_minor+NEW.amount_minor,payment_status=CASE WHEN NOT EXISTS(SELECT 1 FROM commerce_order_items WHERE order_id=NEW.order_id AND quantity>refunded_quantity) THEN 'refunded' ELSE 'partially_refunded' END,aftersale_status=CASE WHEN NOT EXISTS(SELECT 1 FROM commerce_order_items WHERE order_id=NEW.order_id AND quantity>refunded_quantity) THEN 'refunded' ELSE 'partially_refunded' END,status=CASE WHEN NOT EXISTS(SELECT 1 FROM commerce_order_items WHERE order_id=NEW.order_id AND quantity>refunded_quantity) THEN 'refunded' ELSE 'partially_refunded' END,updated=NEW.created WHERE id=NEW.order_id;
 UPDATE commerce_aftersale_requests SET status=CASE WHEN (SELECT payment_status FROM commerce_orders WHERE id=NEW.order_id)='refunded' THEN 'resolved' ELSE 'processing' END,updated=NEW.created WHERE order_id=NEW.order_id AND status IN ('pending','processing');
END

CREATE TRIGGER commerce_refund_check BEFORE INSERT ON commerce_payment_events WHEN NEW.kind='refund' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM commerce_orders o WHERE o.id=NEW.order_id AND o.owner=NEW.owner AND o.environment=NEW.environment AND o.payment_status IN ('paid','partially_refunded')) THEN RAISE(ABORT,'commerce_refund_state') END;
 SELECT CASE WHEN json_array_length(NEW.items)<1 OR EXISTS(SELECT 1 FROM json_each(NEW.items) j LEFT JOIN commerce_order_items i ON i.id=json_extract(j.value,'$.itemId') AND i.order_id=NEW.order_id WHERE i.id IS NULL OR json_type(j.value,'$.quantity')!='integer' OR json_extract(j.value,'$.quantity')<1 OR json_extract(j.value,'$.quantity')>i.quantity-i.refunded_quantity) OR (SELECT count(*) FROM json_each(NEW.items))!=(SELECT count(DISTINCT json_extract(value,'$.itemId')) FROM json_each(NEW.items)) THEN RAISE(ABORT,'commerce_refund_quantity') END;
 SELECT CASE WHEN NEW.amount_minor!=(SELECT sum(json_extract(j.value,'$.quantity')*(i.price_minor+i.unit_shipping_minor+i.unit_tax_minor)) FROM json_each(NEW.items) j JOIN commerce_order_items i ON i.id=json_extract(j.value,'$.itemId') AND i.order_id=NEW.order_id) THEN RAISE(ABORT,'commerce_refund_amount') END;
END

CREATE TRIGGER commerce_reserve_check BEFORE INSERT ON commerce_reservations WHEN NEW.state='held' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM commerce_skus s JOIN commerce_products p ON p.id=s.product_id JOIN commerce_orders o ON o.id=NEW.order_id JOIN commerce_order_items i ON i.order_id=o.id AND i.sku_id=s.id WHERE s.id=NEW.sku_id AND s.environment=o.environment AND p.environment=o.environment AND p.status='published' AND o.payment_status='unpaid' AND s.stock-s.reserved>=NEW.quantity AND s.version=i.price_version) THEN RAISE(ABORT,'commerce_out_of_stock') END;
END

CREATE TRIGGER commission_adjust_apply AFTER INSERT ON commission_adjustments BEGIN
 UPDATE commission_ledger SET refunded_quantity=NEW.refunded_quantity,net_minor=NEW.target_minor,status=CASE WHEN status='settled_bookkeeping' THEN status WHEN NEW.target_minor=0 THEN 'revoked' ELSE status END,updated=NEW.created WHERE id=NEW.ledger_id;
END

CREATE TRIGGER commission_adjust_guard BEFORE INSERT ON commission_adjustments BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM commission_ledger l JOIN commerce_order_items i ON i.id=l.item_id JOIN commerce_payment_events e ON e.id=NEW.source_event AND e.order_id=l.order_id AND e.kind='refund' AND e.status='applied' WHERE l.id=NEW.ledger_id AND l.beneficiary=NEW.beneficiary AND l.currency=NEW.currency AND i.refunded_quantity=NEW.refunded_quantity AND l.refunded_quantity<NEW.refunded_quantity AND NEW.target_minor<=l.net_minor AND NEW.amount_minor=l.net_minor-NEW.target_minor) THEN RAISE(ABORT,'commission_refund_stale') END;
END

CREATE TRIGGER commission_recovery_reserve AFTER INSERT ON commission_statement_lines WHEN NEW.kind='recovery' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM commission_adjustments a JOIN commission_statements s ON s.id=NEW.statement_id WHERE a.id=NEW.source_id AND a.status='pending_recovery' AND a.beneficiary=s.beneficiary AND a.currency=s.currency AND a.amount_minor=-NEW.amount_minor) THEN RAISE(ABORT,'commission_recovery_stale') END;
 UPDATE commission_adjustments SET status='reserved' WHERE id=NEW.source_id;
END

CREATE TRIGGER commission_rule_append BEFORE INSERT ON commission_rules BEGIN
 SELECT CASE WHEN NEW.version!=(SELECT coalesce(max(version),0)+1 FROM commission_rules WHERE rule_id=NEW.rule_id) OR EXISTS(SELECT 1 FROM commission_rules WHERE product_id=NEW.product_id AND kind=NEW.kind AND rule_id!=NEW.rule_id) OR EXISTS(SELECT 1 FROM commission_rules WHERE rule_id=NEW.rule_id AND (product_id!=NEW.product_id OR kind!=NEW.kind)) THEN RAISE(ABORT,'commission_rule_version') END;
END

CREATE TRIGGER commission_statement_close AFTER UPDATE OF status ON commission_statements WHEN NEW.status IN ('booked','cancelled') AND OLD.status!=NEW.status BEGIN
 UPDATE commission_ledger SET status=CASE WHEN NEW.status='booked' THEN 'settled_bookkeeping' WHEN net_minor=0 THEN 'revoked' ELSE 'payable' END WHERE id IN (SELECT source_id FROM commission_statement_lines WHERE statement_id=NEW.id AND kind='earning');
 UPDATE commission_adjustments SET status=CASE WHEN NEW.status='booked' THEN 'offset_booked' ELSE 'pending_recovery' END WHERE id IN (SELECT source_id FROM commission_statement_lines WHERE statement_id=NEW.id AND kind='recovery');
END

CREATE TRIGGER commission_statement_reserve AFTER INSERT ON commission_statement_lines WHEN NEW.kind='earning' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM commission_ledger l JOIN commission_statements s ON s.id=NEW.statement_id WHERE l.id=NEW.source_id AND l.status='payable' AND l.beneficiary=s.beneficiary AND l.currency=s.currency AND l.net_minor=NEW.amount_minor) THEN RAISE(ABORT,'commission_statement_stale') END;
 UPDATE commission_ledger SET status='statement_pending' WHERE id=NEW.source_id;
END

CREATE TRIGGER membership_action_check BEFORE INSERT ON membership_events BEGIN
 SELECT CASE WHEN NEW.kind IN ('cancel_renewal','sandbox_state') AND json_extract(NEW.data,'$._expectedVersion') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM membership_subscriptions s WHERE s.id=NEW.subscription_id AND s.owner=NEW.owner AND s.version=json_extract(NEW.data,'$._expectedVersion')) THEN RAISE(ABORT,'membership_state_changed') END;
 SELECT CASE WHEN NEW.kind='refund_request' AND NOT EXISTS(SELECT 1 FROM commerce_aftersale_requests a JOIN commerce_order_items i ON i.id=json_extract(NEW.data,'$.itemId') AND i.order_id=a.order_id JOIN commerce_orders o ON o.id=a.order_id WHERE a.id=json_extract(NEW.data,'$.id') AND a.owner=NEW.owner AND a.environment=NEW.environment AND o.payment_status IN ('paid','partially_refunded') AND i.quantity>i.refunded_quantity) THEN RAISE(ABORT,'membership_refund_request_changed') END;
END

CREATE TRIGGER membership_activation_check BEFORE UPDATE OF subscription_id ON membership_order_snapshots WHEN OLD.subscription_id IS NULL AND NEW.subscription_id IS NOT NULL BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM membership_subscriptions s JOIN commerce_order_items i ON i.id=NEW.item_id JOIN commerce_orders o ON o.id=i.order_id JOIN commerce_entitlements e ON e.item_id=i.id JOIN commerce_payment_events p ON p.id=NEW.payment_event_id WHERE s.id=NEW.subscription_id AND s.owner=NEW.owner AND s.environment=NEW.environment AND s.current_item_id=NEW.item_id AND s.period_start=NEW.period_start AND s.period_end=NEW.period_end AND s.status='active' AND i.type='membership' AND i.quantity=1 AND i.refunded_quantity=0 AND o.owner=NEW.owner AND o.payment_status IN ('paid','partially_refunded') AND e.owner=NEW.owner AND e.environment=NEW.environment AND e.status='active' AND e.remaining=1 AND p.order_id=NEW.order_id AND p.owner=NEW.owner AND p.environment=NEW.environment AND p.kind='sandbox_pay' AND p.status='applied') THEN RAISE(ABORT,'membership_activation_changed') END;
END

CREATE TRIGGER membership_payment_check BEFORE INSERT ON commerce_payment_events WHEN NEW.kind='sandbox_pay' AND EXISTS(SELECT 1 FROM commerce_order_items WHERE order_id=NEW.order_id AND type='membership') BEGIN
 SELECT CASE WHEN NEW.environment!='sandbox' OR NOT EXISTS(SELECT 1 FROM settings WHERE key='membership_lifecycle' AND json_extract(data,'$.sandboxEnabled')=1) THEN RAISE(ABORT,'membership_payment_disabled') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM commerce_order_items i JOIN commerce_orders o ON o.id=i.order_id LEFT JOIN membership_order_snapshots s ON s.item_id=i.id WHERE i.order_id=NEW.order_id AND i.type='membership' AND (s.item_id IS NULL OR s.owner!=NEW.owner OR s.environment!=NEW.environment OR o.owner!=NEW.owner OR o.payment_status!='unpaid' OR i.quantity!=1 OR i.refunded_quantity!=0 OR i.price_minor!=json_extract(s.data,'$.firstPriceMinor') OR i.price_version!=json_extract(s.data,'$.priceVersion') OR i.currency!=json_extract(s.data,'$.currency'))) THEN RAISE(ABORT,'membership_payment_snapshot_missing_or_changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM membership_order_snapshots s WHERE s.order_id=NEW.order_id AND NOT EXISTS(SELECT 1 FROM membership_purchase_locks l WHERE l.owner=s.owner AND l.environment=s.environment AND l.group_id=s.group_id AND l.order_id=s.order_id)) THEN RAISE(ABORT,'membership_payment_slot_changed') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM membership_order_snapshots s WHERE s.order_id=NEW.order_id AND json_extract(s.data,'$.renewalOf') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM membership_subscriptions sub WHERE sub.id=json_extract(s.data,'$.renewalOf') AND sub.owner=NEW.owner AND sub.environment=NEW.environment AND sub.group_id=s.group_id AND sub.auto_renew=1 AND sub.status NOT IN ('expired','revoked') AND (sub.period_end>NEW.created OR sub.status='grace' AND sub.grace_end>NEW.created))) THEN RAISE(ABORT,'membership_payment_renewal_changed') END;
END

CREATE TRIGGER membership_snapshot_check BEFORE INSERT ON membership_order_snapshots BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM commerce_orders o JOIN commerce_order_items i ON i.order_id=o.id WHERE o.id=NEW.order_id AND o.owner=NEW.owner AND o.environment=NEW.environment AND o.payment_status='unpaid' AND i.id=NEW.item_id AND i.type='membership' AND i.quantity=1 AND i.price_version=json_extract(NEW.data,'$.priceVersion') AND i.price_minor=json_extract(NEW.data,'$.firstPriceMinor') AND i.currency=json_extract(NEW.data,'$.currency')) THEN RAISE(ABORT,'membership_snapshot_order_mismatch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM membership_subscriptions s WHERE s.owner=NEW.owner AND s.environment=NEW.environment AND s.group_id=NEW.group_id AND s.status NOT IN ('expired','revoked') AND (json_extract(NEW.data,'$.renewalOf') IS NULL OR s.id!=json_extract(NEW.data,'$.renewalOf') OR s.auto_renew!=1)) THEN RAISE(ABORT,'membership_duplicate_subscription') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM membership_purchase_locks l JOIN commerce_orders o ON o.id=l.order_id WHERE l.owner=NEW.owner AND l.environment=NEW.environment AND l.group_id=NEW.group_id AND (json_extract(NEW.data,'$.renewalOf') IS NULL OR l.subscription_id IS NULL OR l.subscription_id!=json_extract(NEW.data,'$.renewalOf') OR (EXISTS(SELECT 1 FROM membership_order_snapshots q WHERE q.order_id=l.order_id AND q.subscription_id IS NULL) AND (o.payment_status IN ('paid','partially_refunded') OR o.payment_status='unpaid' AND o.reserved_until>NEW.created)))) THEN RAISE(ABORT,'membership_duplicate_checkout') END;
END

CREATE TRIGGER membership_snapshot_lock AFTER INSERT ON membership_order_snapshots BEGIN
 INSERT INTO membership_purchase_locks SELECT NEW.owner,NEW.environment,NEW.group_id,NEW.order_id,json_extract(NEW.data,'$.renewalOf'),o.reserved_until FROM commerce_orders o WHERE o.id=NEW.order_id ON CONFLICT(owner,environment,group_id) DO UPDATE SET order_id=excluded.order_id,expires=excluded.expires;
END
